for (const item of $input.all()) {
  let rawOutput = item.json.output;

  if (rawOutput && typeof rawOutput === 'string') {
    const regexMatch = rawOutput.match(/```json\s*([\s\S]*?)\s*```/);
    const jsonString = regexMatch ? regexMatch[1] : rawOutput;

    try {
      const parsedJson = JSON.parse(jsonString.trim());
      item.json = parsedJson;

    } catch (error) {
      item.json.error = "No se pudo parsear el output del LLM como JSON.";
      item.json.raw_output = rawOutput;
    }
  }
}

return $input.all();

